import math

def calculate_K(n):
    if 2 * n - 1 == 0:
        return "undefined (division by zero)"
    try:
        numerator = 3 * (math.factorial(n + 2) + 1)
        denominator = 2 * n - 1
        K = numerator / denominator
        return K
    except ValueError:
        return "Error (Factorial input issue)"

n_values = range(11)
results = {}
integer_n = []

for n in n_values:
    K_value = calculate_K(n)
    results[n] = K_value
    if isinstance(K_value, (int, float)) and K_value == int(K_value):
        integer_n.append(n)

print(f"Results for n=0 to n=10: {results}")
print(f"Values of n where K is an integer: {integer_n}")

def check(n):
    if n < 0:
        return False
    denominator = 2 * n - 1
    if denominator == 0:
        return False # Should not happen for integer n

    # Calculate numerator: 3 * ((n+2)! + 1)
    import math
    try:
        numerator = 3 * (math.factorial(n + 2) + 1)
    except OverflowError:
        # Handle very large n if needed, but for small tests this is fine
        return None 

    if numerator % denominator == 0:
        return True
    else:
        return False

# Test n=0 through n=10
for n in range(11):
    result = check(n)
    print(f"n={n}: Is integer? {result}")
